import type { AnimatableProp, Asset, Clip, Id, Project } from "./model";
import { clipEnd, trackClips } from "./model";
import type { Time } from "./time";

/**
 * Every edit — from the UI, the AI tool, templates — is one of these commands.
 * Commands are plain data so they can be logged, replayed and generated by the agent.
 */
export type Command =
  | { type: "addAsset"; asset: Asset }
  | { type: "addClip"; trackId: Id; assetId: Id; start?: Time; clipId?: Id }
  | { type: "addTextClip"; trackId: Id; text: string; start: Time; duration: Time; clipId?: Id }
  | { type: "split"; clipId: Id; at: Time; newClipId?: Id }
  | { type: "trim"; clipId: Id; edge: "start" | "end"; to: Time }
  | { type: "move"; clipId: Id; start: Time; trackId?: Id }
  | { type: "delete"; clipId: Id; ripple?: boolean }
  | { type: "setProps"; clipId: Id; props: Partial<Pick<Clip, "speed" | "volume" | "x" | "y" | "scale" | "rotation" | "opacity" | "text">> }
  | { type: "setKeyframe"; clipId: Id; prop: AnimatableProp; t: Time; value: number }
  | { type: "removeKeyframe"; clipId: Id; prop: AnimatableProp; t: Time }
  | { type: "setCanvas"; width: number; height: number };

let counter = 0;
const uid = (prefix: string) => `${prefix}${Date.now().toString(36)}${(counter++).toString(36)}`;

export class CommandError extends Error {}

function getClip(p: Project, id: Id): Clip {
  const c = p.clips[id];
  if (!c) throw new CommandError(`clip not found: ${id}`);
  return c;
}

function withClip(p: Project, c: Clip): Project {
  return { ...p, clips: { ...p.clips, [c.id]: c } };
}

function defaults(): Omit<Clip, "id" | "trackId" | "kind" | "start" | "duration" | "sourceIn"> {
  return { speed: 1, volume: 1, x: 0, y: 0, scale: 1, rotation: 0, opacity: 1, keyframes: {} };
}

/** First free time on a track at or after `from` so a new clip never overlaps. */
function freeStart(p: Project, trackId: Id, from: Time, duration: Time): Time {
  let start = from;
  for (const c of trackClips(p, trackId)) {
    if (start < clipEnd(c) && start + duration > c.start) start = clipEnd(c);
  }
  return start;
}

function overlaps(p: Project, trackId: Id, start: Time, duration: Time, ignore: Id): boolean {
  return trackClips(p, trackId).some((c) => c.id !== ignore && start < clipEnd(c) && start + duration > c.start);
}

export function apply(p: Project, cmd: Command): Project {
  switch (cmd.type) {
    case "addAsset":
      return { ...p, assets: { ...p.assets, [cmd.asset.id]: cmd.asset } };

    case "addClip": {
      const track = p.tracks.find((t) => t.id === cmd.trackId);
      const asset = p.assets[cmd.assetId];
      if (!track) throw new CommandError(`track not found: ${cmd.trackId}`);
      if (!asset) throw new CommandError(`asset not found: ${cmd.assetId}`);
      if (track.kind === "audio" && asset.kind === "image") throw new CommandError("cannot put an image on an audio track");
      const duration = asset.kind === "image" ? 5_000_000 : asset.duration;
      const start = freeStart(p, track.id, cmd.start ?? 0, duration);
      const clip: Clip = {
        id: cmd.clipId ?? uid("c"), trackId: track.id, kind: "media", assetId: asset.id,
        start, duration, sourceIn: 0, ...defaults(),
      };
      return {
        ...withClip(p, clip),
        tracks: p.tracks.map((t) => (t.id === track.id ? { ...t, clipIds: [...t.clipIds, clip.id] } : t)),
      };
    }

    case "addTextClip": {
      const track = p.tracks.find((t) => t.id === cmd.trackId);
      if (!track || track.kind !== "video") throw new CommandError("text needs a video track");
      if (cmd.duration <= 0) throw new CommandError("duration must be positive");
      const clip: Clip = {
        id: cmd.clipId ?? uid("c"), trackId: track.id, kind: "text", text: cmd.text,
        start: cmd.start, duration: cmd.duration, sourceIn: 0, ...defaults(),
      };
      return {
        ...withClip(p, clip),
        tracks: p.tracks.map((t) => (t.id === track.id ? { ...t, clipIds: [...t.clipIds, clip.id] } : t)),
      };
    }

    case "split": {
      const c = getClip(p, cmd.clipId);
      if (cmd.at <= c.start || cmd.at >= clipEnd(c)) throw new CommandError("split point must be inside the clip");
      const leftDur = cmd.at - c.start;
      const left: Clip = { ...c, duration: leftDur };
      const right: Clip = {
        ...c, id: cmd.newClipId ?? uid("c"), start: cmd.at, duration: c.duration - leftDur,
        sourceIn: c.sourceIn + Math.round(leftDur * c.speed),
        keyframes: {}, // keyframes stay on the left half; re-split by the user if needed
      };
      return {
        ...withClip(withClip(p, left), right),
        tracks: p.tracks.map((t) => (t.id === c.trackId ? { ...t, clipIds: [...t.clipIds, right.id] } : t)),
      };
    }

    case "trim": {
      const c = getClip(p, cmd.clipId);
      if (cmd.edge === "start") {
        const to = Math.min(Math.max(cmd.to, c.start - c.sourceIn / c.speed), clipEnd(c) - 1);
        const delta = to - c.start;
        const n: Clip = { ...c, start: to, duration: c.duration - delta, sourceIn: c.sourceIn + Math.round(delta * c.speed) };
        if (overlaps(p, c.trackId, n.start, n.duration, c.id)) throw new CommandError("trim would overlap a neighbour");
        return withClip(p, n);
      }
      const to = Math.max(cmd.to, c.start + 1);
      const n: Clip = { ...c, duration: to - c.start };
      if (c.kind === "media" && c.assetId) {
        const a = p.assets[c.assetId];
        if (a && a.kind !== "image" && n.sourceIn + n.duration * n.speed > a.duration + 1) {
          throw new CommandError("cannot extend past the end of the source media");
        }
      }
      if (overlaps(p, c.trackId, n.start, n.duration, c.id)) throw new CommandError("trim would overlap a neighbour");
      return withClip(p, n);
    }

    case "move": {
      const c = getClip(p, cmd.clipId);
      const trackId = cmd.trackId ?? c.trackId;
      const dest = p.tracks.find((t) => t.id === trackId);
      if (!dest) throw new CommandError(`track not found: ${trackId}`);
      const start = Math.max(0, cmd.start);
      if (overlaps(p, trackId, start, c.duration, c.id)) throw new CommandError("move would overlap another clip");
      const moved = withClip(p, { ...c, start, trackId });
      if (trackId === c.trackId) return moved;
      return {
        ...moved,
        tracks: p.tracks.map((t) =>
          t.id === c.trackId ? { ...t, clipIds: t.clipIds.filter((i) => i !== c.id) }
          : t.id === trackId ? { ...t, clipIds: [...t.clipIds, c.id] } : t),
      };
    }

    case "delete": {
      const c = getClip(p, cmd.clipId);
      const clips = { ...p.clips };
      delete clips[c.id];
      if (cmd.ripple) {
        for (const o of trackClips(p, c.trackId)) {
          if (o.start >= clipEnd(c)) clips[o.id] = { ...o, start: o.start - c.duration };
        }
      }
      return {
        ...p, clips,
        tracks: p.tracks.map((t) => (t.id === c.trackId ? { ...t, clipIds: t.clipIds.filter((i) => i !== c.id) } : t)),
      };
    }

    case "setProps": {
      const c = getClip(p, cmd.clipId);
      const props = { ...cmd.props };
      if (props.speed !== undefined) {
        if (props.speed < 0.1 || props.speed > 16) throw new CommandError("speed must be between 0.1 and 16");
        // keep the same source range: duration scales inversely with speed
        const sourceSpan = c.duration * c.speed;
        const newDuration = Math.round(sourceSpan / props.speed);
        if (overlaps(p, c.trackId, c.start, newDuration, c.id)) throw new CommandError("speed change would overlap a neighbour");
        return withClip(p, { ...c, ...props, duration: newDuration });
      }
      return withClip(p, { ...c, ...props });
    }

    case "setKeyframe": {
      const c = getClip(p, cmd.clipId);
      if (cmd.t < 0 || cmd.t > c.duration) throw new CommandError("keyframe time outside clip");
      const list = (c.keyframes[cmd.prop] ?? []).filter((k) => k.t !== cmd.t);
      list.push({ t: cmd.t, value: cmd.value });
      list.sort((a, b) => a.t - b.t);
      return withClip(p, { ...c, keyframes: { ...c.keyframes, [cmd.prop]: list } });
    }

    case "removeKeyframe": {
      const c = getClip(p, cmd.clipId);
      const list = (c.keyframes[cmd.prop] ?? []).filter((k) => k.t !== cmd.t);
      return withClip(p, { ...c, keyframes: { ...c.keyframes, [cmd.prop]: list } });
    }

    case "setCanvas":
      return { ...p, width: cmd.width, height: cmd.height };
  }
}
